0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":3439,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 11.54\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T91c,"])self.__next_f.push([1,"Kṛṣṇa can be understood only by the process of undivided devotional service. He explicitly explains this in this verse so that unauthorized commentators, who try to understand Bhagavad-gītā by the speculative process, will know that they are simply wasting their time. No one can understand Kṛṣṇa or how He came from parents in a four-handed form and at once changed Himself into a two-handed form. These things are very difficult to understand by study of the Vedas or by philosophical speculation. Therefore it is clearly stated here that no one can see Him or enter into understanding of these matters. Those who, however, are very experienced students of Vedic literature can learn about Him from the Vedic literature in so many ways. There are so many rules and regulations, and if one at all wants to understand Kṛṣṇa, he must follow the regulative principles described in the authoritative literature. One can perform penance in accordance with those principles. For example, to undergo serious penances one may observe fasting on Janmāṣṭamī, the day on which Kṛṣṇa appeared, and on the two days of Ekādaśī (the eleventh day after the new moon and the eleventh day after the full moon). As far as charity is concerned, it is plain that charity should be given to the devotees of Kṛṣṇa who are engaged in His devotional service to spread the Kṛṣṇa philosophy, or Kṛṣṇa consciousness, throughout the world. Kṛṣṇa consciousness is a benediction to humanity. Lord Caitanya was appreciated by Rūpa Gosvāmī as the most munificent man of charity because love of Kṛṣṇa, which is very difficult to achieve, was distributed freely by Him. So if one gives some amount of his money to persons involved in distributing Kṛṣṇa consciousness, that charity, given to spread Kṛṣṇa consciousness, is the greatest charity in the world. And if one worships as prescribed in the temple (in the temples in India there is always some statue, usually of Viṣṇu or Kṛṣṇa), that is a chance to progress by offering worship and respect to the Supreme Personality of Godhead. For the beginners in devotional service to the Lord, temple worship is essential, and this is confirmed in the Vedic literature (Śvetāśvatara Upaniṣad 6.23):"])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":3439,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"54\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXT 54\",\"advanced_view_url_path\":\"/en/library/bg/11/advanced-view/#bb3027\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/11/54/\"},{\"display_name\":\"Čeština (Czech)\",\"language_code\":\"cs\",\"enabled\":true,\"url_path\":\"/cs/library/bg/11/54/\"},{\"display_name\":\"Dansk (Danish)\",\"language_code\":\"da\",\"enabled\":true,\"url_path\":\"/da/library/bg/11/54/\"},{\"display_name\":\"Deutsch (German)\",\"language_code\":\"de\",\"enabled\":true,\"url_path\":\"/de/library/bg/11/54/\"},{\"display_name\":\"English\",\"language_code\":\"en\",\"enabled\":true,\"url_path\":\"/en/library/bg/11/54/\"},{\"display_name\":\"Español (Spanish)\",\"language_code\":\"es\",\"enabled\":true,\"url_path\":\"/es/library/bg/11/54/\"},{\"display_name\":\"Eesti keel (Estonian)\",\"language_code\":\"et\",\"enabled\":true,\"url_path\":\"/et/library/bg/11/54/\"},{\"display_name\":\"Suomen kieli (Finnish)\",\"language_code\":\"fi\",\"enabled\":false,\"url_path\":\"/fi/\"},{\"display_name\":\"Français (French)\",\"language_code\":\"fr\",\"enabled\":true,\"url_path\":\"/fr/library/bg/11/54/\"},{\"display_name\":\"Hrvatski (Croatian)\",\"language_code\":\"hr\",\"enabled\":true,\"url_path\":\"/hr/library/bg/11/54/\"},{\"display_name\":\"Magyar (Hungarian)\",\"language_code\":\"hu\",\"enabled\":true,\"url_path\":\"/hu/library/bg/11/54/\"},{\"display_name\":\"日本語 (Japanese)\",\"language_code\":\"ja\",\"enabled\":true,\"url_path\":\"/ja/library/bg/11/54/\"},{\"display_name\":\"한국어 (Korean)\",\"language_code\":\"ko\",\"enabled\":true,\"url_path\":\"/ko/library/bg/11/54/\"},{\"display_name\":\"Lietuvių kalba (Lithuanian)\",\"language_code\":\"lt\",\"enabled\":true,\"url_path\":\"/lt/library/bg/11/54/\"},{\"display_name\":\"Nederlands (Dutch)\",\"language_code\":\"nl\",\"enabled\":true,\"url_path\":\"/nl/library/bg/11/54/\"},{\"display_name\":\"Polski (Polish)\",\"language_code\":\"pl\",\"enabled\":true,\"url_path\":\"/pl/library/bg/11/54/\"},{\"display_name\":\"Português (Portuguese)\",\"language_code\":\"pt-br\",\"enabled\":true,\"url_path\":\"/pt-br/library/bg/11/54/\"},{\"display_name\":\"Русский (Russian)\",\"language_code\":\"ru\",\"enabled\":true,\"url_path\":\"/ru/library/bg/11/54/\"},{\"display_name\":\"Slovenčina (Slovak)\",\"language_code\":\"sk\",\"enabled\":true,\"url_path\":\"/sk/library/bg/11/54/\"},{\"display_name\":\"Slovenščina (Slovenian)\",\"language_code\":\"sl\",\"enabled\":true,\"url_path\":\"/sl/library/bg/11/54/\"},{\"display_name\":\"Українська мова (Ukrainian)\",\"language_code\":\"uk\",\"enabled\":true,\"url_path\":\"/uk/library/bg/11/54/\"},{\"display_name\":\"isiZulu (Zulu)\",\"language_code\":\"zu\",\"enabled\":false,\"url_path\":\"/zu/\"}],\"breadcrumb\":[{\"url_path\":\"/en/library/\",\"title\":\"Library\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/11/\",\"title\":\"Chapter Eleven: The Universal Form\"}],\"url_path\":\"/en/library/bg/11/54/\",\"bb\":3027,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/11/53/\",\"title\":\"TEXT 53\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/11/55/\",\"title\":\"TEXT 55\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":3440,\"bb\":568332,\"url_path\":\"/en/library/bg/11/54/devanagari/\",\"body_final\":\"भक्त्य‍ा त्वनन्यया शक्य अहमेवंविधोऽर्जुन ।
ज्ञातुं द्रष्टुं च तत्त्वेन प्रवेष्टुं च परन्तप ॥ ५४ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3441,\"bb\":3028,\"url_path\":\"/en/library/bg/11/54/b3028/\",\"body_value\":\"bhaktyā tv ananyayā śakya
aham evaṁ-vidho ’rjuna
jñātuṁ draṣṭuṁ ca tattvena
praveṣṭuṁ ca paran-tapa\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":3442,\"bb\":3029,\"url_path\":\"/en/library/bg/11/54/b3029/\",\"shadow_value\":\"bhaktyā – by devotional service; tu – but; ananyayā – without being mixed with fruitive activities or speculative knowledge; śakyaḥ – possible; aham – I; evam-vidhaḥ – like this; arjuna – O Arjuna; jñātum – to know; draṣṭum – to see; ca – and; tattvena – in fact; praveṣṭum – to enter into; ca – also; param-tapa – O subduer of the enemy.\",\"word_for_word_value\":[{\"word\":\"bhaktyā\",\"translation\":\"by devotional service\"},{\"word\":\"tu\",\"translation\":\"but\"},{\"word\":\"ananyayā\",\"translation\":\"without being mixed with fruitive activities or speculative knowledge\"},{\"word\":\"śakyaḥ\",\"translation\":\"possible\"},{\"word\":\"aham\",\"translation\":\"I\"},{\"word\":\"evam-vidhaḥ\",\"translation\":\"like this\"},{\"word\":\"arjuna\",\"translation\":\"O Arjuna\"},{\"word\":\"jñātum\",\"translation\":\"to know\"},{\"word\":\"draṣṭum\",\"translation\":\"to see\"},{\"word\":\"ca\",\"translation\":\"and\"},{\"word\":\"tattvena\",\"translation\":\"in fact\"},{\"word\":\"praveṣṭum\",\"translation\":\"to enter into\"},{\"word\":\"ca\",\"translation\":\"also\"},{\"word\":\"param-tapa\",\"translation\":\"O subduer of the enemy\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":3443,\"bb\":3030,\"url_path\":\"/en/library/bg/11/54/b3030/\",\"body_value\":\"My dear Arjuna, only by undivided devotional service can I be understood as I am, standing before you, and can thus be seen directly. Only in this way can you enter into the mysteries of My understanding.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3444,\"bb\":3031,\"url_path\":\"/en/library/bg/11/54/b3031/\",\"body_value\":\"$25\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3445,\"bb\":3032,\"url_path\":\"/en/library/bg/11/54/b3032/\",\"body_value\":\"yasya deve parā bhaktir
yathā deve tathā gurau
tasyaite kathitā hy arthāḥ
prakāśante mahātmanaḥ\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3446,\"bb\":3033,\"url_path\":\"/en/library/bg/11/54/b3033/\",\"body_value\":\"One who has unflinching devotion for the Supreme Lord and is directed by the spiritual master, in whom he has similar unflinching faith, can see the Supreme Personality of Godhead by revelation. One cannot understand Kṛṣṇa by mental speculation. For one who does not take personal training under the guidance of a bona fide spiritual master, it is impossible to even begin to understand Kṛṣṇa. The word tu is specifically used here to indicate that no other process can be used, can be recommended, or can be successful in understanding Kṛṣṇa.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3447,\"bb\":3034,\"url_path\":\"/en/library/bg/11/54/b3034/\",\"body_value\":\"The personal forms of Kṛṣṇa, the two-handed form and the four-handed, are described as su-durdarśam, very difficult to see. They are completely different from the temporary universal form shown to Arjuna. The four-handed form of Nārāyaṇa and the two-handed form of Kṛṣṇa are eternal and transcendental, whereas the universal form exhibited to Arjuna is temporary. The words tvad anyena na dṛṣṭa-pūrvam (verse 47) state that before Arjuna, no one had seen that universal form. Also, they suggest that amongst the devotees there was no necessity of showing it. That form was exhibited by Kṛṣṇa at the request of Arjuna so that in the future, when one represents himself as an incarnation of God, people can ask to see his universal form.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3448,\"bb\":3035,\"url_path\":\"/en/library/bg/11/54/b3035/\",\"body_value\":\"The word na, used repeatedly in the previous verse, indicates that one should not be very much proud of such credentials as an academic education in Vedic literature. One must take to the devotional service of Kṛṣṇa. Only then can one attempt to write commentaries on Bhagavad-gītā.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3449,\"bb\":3036,\"url_path\":\"/en/library/bg/11/54/b3036/\",\"body_value\":\"Kṛṣṇa changes from the universal form to the four-handed form of Nārāyaṇa and then to His own natural form of two hands. This indicates that the four-handed forms and other forms mentioned in Vedic literature are all emanations of the original two-handed Kṛṣṇa. He is the origin of all emanations. Kṛṣṇa is distinct even from these forms, what to speak of the impersonal conception. As far as the four-handed forms of Kṛṣṇa are concerned, it is stated clearly that even the most identical four-handed form of Kṛṣṇa (which is known as Mahā-viṣṇu, who is lying on the cosmic ocean and from whose breathing so many innumerable universes are passing out and entering) is also an expansion of the Supreme Lord. As stated in the Brahma-saṁhitā (5.48),\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3450,\"bb\":3037,\"url_path\":\"/en/library/bg/11/54/b3037/\",\"body_value\":\"yasyaika-niśvasita-kālam athāvalambya
jīvanti loma-vila-jā jagad-aṇḍa-nāthāḥ
viṣṇur mahān sa iha yasya kalā-viśeṣo
govindam ādi-puruṣaṁ tam ahaṁ bhajāmi\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3451,\"bb\":3038,\"url_path\":\"/en/library/bg/11/54/b3038/\",\"body_value\":\"“The Mahā-viṣṇu, into whom all the innumerable universes enter and from whom they come forth again simply by His breathing process, is a plenary expansion of Kṛṣṇa. Therefore I worship Govinda, Kṛṣṇa, the cause of all causes.” Therefore one should conclusively worship the personal form of Kṛṣṇa as the Supreme Personality of Godhead who has eternal bliss and knowledge. He is the source of all forms of Viṣṇu, He is the source of all forms of incarnation, and He is the original Supreme Personality, as confirmed in Bhagavad-gītā.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3452,\"bb\":3039,\"url_path\":\"/en/library/bg/11/54/b3039/\",\"body_value\":\"In the Vedic literature (Gopāla-tāpanī Upaniṣad 1.1) the following statement appears:\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3453,\"bb\":3040,\"url_path\":\"/en/library/bg/11/54/b3040/\",\"body_value\":\"sac-cid-ānanda-rūpāya
kṛṣṇāyākliṣṭa-kāriṇe
namo vedānta-vedyāya
gurave buddhi-sākṣiṇe\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3454,\"bb\":3041,\"url_path\":\"/en/library/bg/11/54/b3041/\",\"body_value\":\"“I offer my respectful obeisances unto Kṛṣṇa, who has a transcendental form of bliss, eternity and knowledge. I offer my respect to Him, because understanding Him means understanding the Vedas, and He is therefore the supreme spiritual master.” Then it is said, kṛṣṇo vai paramaṁ daivatam: “Kṛṣṇa is the Supreme Personality of Godhead.” (Gopāla-tāpanī Upaniṣad 1.3) Eko vaśī sarva-gaḥ kṛṣṇa īḍyaḥ: “That one Kṛṣṇa is the Supreme Personality of Godhead, and He is worshipable.” Eko ’pi san bahudhā yo ’vabhāti: “Kṛṣṇa is one, but He is manifested in unlimited forms and expanded incarnations.” (Gopāla-tāpanī Upaniṣad 1.21)\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3455,\"bb\":3042,\"url_path\":\"/en/library/bg/11/54/b3042/\",\"body_value\":\"The Brahma-saṁhitā (5.1) says,\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3456,\"bb\":3043,\"url_path\":\"/en/library/bg/11/54/b3043/\",\"body_value\":\"īśvaraḥ paramaḥ kṛṣṇaḥ
sac-cid-ānanda-vigrahaḥ
anādir ādir govindaḥ
sarva-kāraṇa-kāraṇam\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3457,\"bb\":3044,\"url_path\":\"/en/library/bg/11/54/b3044/\",\"body_value\":\"“The Supreme Personality of Godhead is Kṛṣṇa, who has a body of eternity, knowledge and bliss. He has no beginning, for He is the beginning of everything. He is the cause of all causes.”\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3458,\"bb\":3045,\"url_path\":\"/en/library/bg/11/54/b3045/\",\"body_value\":\"Elsewhere it is said, yatrāvatīrṇaṁ kṛṣṇākhyaṁ paraṁ brahma narākṛti: “The Supreme Absolute Truth is a person, His name is Kṛṣṇa, and He sometimes descends on this earth.” Similarly, in the Śrīmad-Bhāgavatam we find a description of all kinds of incarnations of the Supreme Personality of Godhead, and in this list the name of Kṛṣṇa also appears. But then it is said that this Kṛṣṇa is not an incarnation of God but is the original Supreme Personality of Godhead Himself (ete cāṁśa-kalāḥ puṁsaḥ kṛṣṇas tu bhagavān svayam).\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3459,\"bb\":3046,\"url_path\":\"/en/library/bg/11/54/b3046/\",\"body_value\":\"Similarly, in Bhagavad-gītā the Lord says, mattaḥ parataraṁ nānyat: “There is nothing superior to My form as the Personality of Godhead Kṛṣṇa.” He also says elsewhere in Bhagavad-gītā, aham ādir hi devānām: “I am the origin of all the demigods.” And after understanding Bhagavad-gītā from Kṛṣṇa, Arjuna also confirms this in the following words: paraṁ brahma paraṁ dhāma pavitraṁ paramaṁ bhavān, “I now fully understand that You are the Supreme Personality of Godhead, the Absolute Truth, and that You are the refuge of everything.” Therefore the universal form which Kṛṣṇa showed to Arjuna is not the original form of God. The original is the Kṛṣṇa form. The universal form, with its thousands and thousands of heads and hands, is manifest just to draw the attention of those who have no love for God. It is not God’s original form.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3460,\"bb\":3047,\"url_path\":\"/en/library/bg/11/54/b3047/\",\"body_value\":\"The universal form is not attractive for pure devotees, who are in love with the Lord in different transcendental relationships. The Supreme Godhead exchanges transcendental love in His original form of Kṛṣṇa. Therefore to Arjuna, who was so intimately related with Kṛṣṇa in friendship, this form of the universal manifestation was not pleasing; rather, it was fearful. Arjuna, who was a constant companion of Kṛṣṇa’s, must have had transcendental eyes; he was not an ordinary man. Therefore he was not captivated by the universal form. This form may seem wonderful to persons who are involved in elevating themselves by fruitive activities, but to persons who are engaged in devotional service the two-handed form of Kṛṣṇa is the most dear.\"}]}],\"short_title\":\"Bg. 11.54\",\"medium_title\":\"Bhagavad-gītā As It Is 11.54\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L26\",\"$L27\",\"$L28\"]}]\n"])self.__next_f.push([1,"2a:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n30:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n26:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[