6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":3478,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 12.1\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T42e,And so, factually, there are two classes of transcendentalists. Now Arjuna is trying to settle the question of which process is easier and which of the classes is most perfect. In other words, he is clarifying his own position because he is attached to the personal form of Kṛṣṇa. He is not attached to the impersonal Brahman. He wants to know whether his position is secure. The impersonal manifestation, either in this material world or in the spiritual world of the Supreme Lord, is a problem for meditation. Actually, one cannot perfectly conceive of the impersonal feature of the Absolute Truth. Therefore Arjuna wants to say, “What is the use of such a waste of time?” Arjuna experienced in the Eleventh Chapter that to be attached to the personal form of Kṛṣṇa is best because he could thus understand all other forms at the same time and there was no disturbance to his love for Kṛṣṇa. This important question asked of Kṛṣṇa by Arjuna will clarify the distinction between the impersonal and personal conceptions of the Absolute Truth."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":3478,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"1\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXT 1\",\"advanced_view_url_path\":\"/en/library/bg/12/advanced-view/#bb3065\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/12/1/\"},{\"display_name\":\"Čeština (Czech)\",\"language_code\":\"cs\",\"enabled\":true,\"url_path\":\"/cs/library/bg/12/1/\"},{\"display_name\":\"Dansk (Danish)\",\"language_code\":\"da\",\"enabled\":true,\"url_path\":\"/da/library/bg/12/1/\"},{\"display_name\":\"Deutsch (German)\",\"language_code\":\"de\",\"enabled\":true,\"url_path\":\"/de/library/bg/12/1/\"},{\"display_name\":\"English\",\"language_code\":\"en\",\"enabled\":true,\"url_path\":\"/en/library/bg/12/1/\"},{\"display_name\":\"Español (Spanish)\",\"language_code\":\"es\",\"enabled\":true,\"url_path\":\"/es/library/bg/12/1/\"},{\"display_name\":\"Eesti keel (Estonian)\",\"language_code\":\"et\",\"enabled\":true,\"url_path\":\"/et/library/bg/12/1/\"},{\"display_name\":\"Suomen kieli (Finnish)\",\"language_code\":\"fi\",\"enabled\":false,\"url_path\":\"/fi/\"},{\"display_name\":\"Français (French)\",\"language_code\":\"fr\",\"enabled\":true,\"url_path\":\"/fr/library/bg/12/1/\"},{\"display_name\":\"Hrvatski (Croatian)\",\"language_code\